<?php
namespace App\Services; use App\Models\DeliveryZoneModel;
class DeliveryService{public function calculate(int $districtId,int $upazilaId,float $subtotal):array{$m=new DeliveryZoneModel();$zone=$m->where(['status'=>'active','upazila_id'=>$upazilaId])->orderBy('priority','DESC')->first();if(!$zone)$zone=(new DeliveryZoneModel())->where(['status'=>'active','zone_type'=>'district','district_id'=>$districtId])->orderBy('priority','DESC')->first();if(!$zone)$zone=(new DeliveryZoneModel())->where(['status'=>'active','zone_type'=>'all_bangladesh'])->orderBy('priority','DESC')->first();if(!$zone)throw new \RuntimeException('এই ঠিকানার ডেলিভারি চার্জ এখনো নির্ধারণ করা হয়নি।');$charge=(float)$zone['delivery_charge'];if($zone['free_delivery_minimum']!==null&&$subtotal>=(float)$zone['free_delivery_minimum'])$charge=0;return ['charge'=>$charge,'estimate'=>$zone['estimated_delivery_text'],'zone'=>$zone];}}
